  ) as proposed(content_key, version_id, topic_code, skill_code, run_tag)
  join app.content_items ci on ci.content_key = proposed.content_key
    and ci.exam_pack_version_id = '548f06be-ccf4-426d-b82b-b424137a4438'::uuid and ci.status = 'published'
  join app.content_item_versions civ on civ.id = proposed.version_id
    and civ.content_item_id = ci.id and civ.status = 'published'
  join app.content_item_cells prim on prim.content_item_version_id = civ.id
    and prim.is_primary and prim.topic_code = proposed.topic_code
  join app.taxonomy_cells tc on tc.taxonomy_source_version = prim.taxonomy_source_version
    and tc.topic_code = prim.topic_code and tc.skill_code = proposed.skill_code
  where not exists (select 1 from app.content_item_cells existing
    where existing.content_item_version_id = civ.id and existing.skill_code is not null);
  get diagnostics inserted_count = row_count;
  if inserted_count <> 390 then
    raise exception 'TASK-0050 expected 390 new skill cells, inserted %', inserted_count;
  end if;
